passages:
{"acquirer": [{"quote": "Victory will merge with and into QNB, with QNB continuing as the surviving corporation.", "location": "qnbc-20260114.htm | The Merger, page 11", "relevance_score": 5}, {"quote": "QNB Corp. is a bank holding company headquartered in Quakertown, Pennsylvania, and the parent company of QNB Bank, a Pennsylvania state chartered bank.", "location": "qnbc-20260114.htm | The Companies — QNB Corp., page 99", "relevance_score": 5}], "target": [{"quote": "Victory will merge with and into QNB, with QNB continuing as the surviving corporation.", "location": "qnbc-20260114.htm | The Merger, page 11", "relevance_score": 5}, {"quote": "The Victory Bancorp, Inc. is a bank holding company headquartered in Limerick Township, Pennsylvania, and the parent company of The Victory Bank, a Pennsylvania state chartered bank that offers a full range of banking services from four offices across Montgomery and Berks Counties, Pennsylvania.", "location": "qnbc-20260114.htm | Summary — Information about Victory, page 11", "relevance_score": 5}], "consideration_type": [{"quote": "each share of Victory common stock issued and outstanding immediately prior to the effective time of the merger will be converted into the right to receive 0.5500 shares (the “exchange ratio”) of QNB common stock (the consideration such holder receives, the “merger consideration”).", "location": "qnbc-20260114.htm | Merger Consideration, page 12", "relevance_score": 5}, {"quote": "QNB will not issue any fractional shares of QNB common stock in the merger. Instead, a Victory shareholder who otherwise would have received a fraction of a share of QNB common stock will receive an amount in cash (without interest and rounded to the nearest cent)", "location": "qnbc-20260114.htm | Questions and Answers, page 2", "relevance_score": 5}], "cash_consideration": [{"quote": "QNB will not issue any fractional shares of QNB common stock in the merger. Instead, a Victory shareholder who otherwise would have received a fraction of a share of QNB common stock will receive an amount in cash (without interest and rounded to the nearest cent) determined by multiplying (1) the average of the daily closing prices on the OTC for shares of QNB common stock for the five consecutive full trading days ending two trading days immediately preceding the date of closing of the merger by (2) the fraction of a share (rounded to the nearest one‑thousandth of a share when expressed in decimal form) of QNB common stock to which such shareholder would otherwise be entitled to receive.", "location": "qnbc-20260114.htm | Questions and Answers, page 2", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "each share of Victory common stock issued and outstanding immediately prior to the effective time of the merger will be converted into the right to receive 0.5500 shares (the “exchange ratio”) of QNB common stock (the consideration such holder receives, the “merger consideration”).", "location": "qnbc-20260114.htm | Merger Consideration, page 12", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "Victory will hold a special meeting of shareholders on February 19, 2026, at 11:00 a.m., local time, at 548 N. Lewis Road, Limerick, PA 19468. At the special meeting, Victory shareholders will be asked to vote on the Victory merger proposal and, if necessary, the Victory adjournment proposal.", "location": "qnbc-20260114.htm | Victory Special Meeting of Shareholders, page 14", "relevance_score": 5}, {"quote": "QNB will hold a virtual special meeting of its shareholders on February 19, 2026, at 11:00 a.m., local time, at meetnow.global/MY6AUXU. At the special meeting, QNB shareholders will be asked to vote on the QNB merger proposal and the QNB adjournment proposal.", "location": "qnbc-20260114.htm | QNB Special Meeting of Shareholders, page 14", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of QNB and Victory to complete the merger are subject to the fulfillment or written waiver of each of the following conditions:
•
the merger agreement and the merger must be duly adopted and approved by the requisite vote of the shareholders of Victory and shareholders of QNB;
•
all regulatory approvals required to consummate the merger and the transactions contemplated thereby must have been obtained and shall remain in full force and effect and all statutory waiting periods in respect thereof shall have expired", "location": "qnbc-20260114.htm | The Merger Agreement — Conditions to Complete the Merger, page 87", "relevance_score": 5}, {"quote": "no governmental authority of competent jurisdiction shall have enacted, issued, promulgated, enforced or entered any statute, rule, regulation, judgment, decree, injunction or other order (whether temporary, preliminary or permanent) which is in effect and prohibits consummation of the transactions contemplated by the merger agreement;
•
the QNB common stock to be issued in the merger must be authorized for quotation on the OTC;
•
this registration statement of which this joint proxy statement/prospectus is a part must have been declared effective by the SEC and must not be subject to any stop order or any threatened stop order by the SEC; and
•
Victory procures the Tail Policy.", "location": "qnbc-20260114.htm | The Merger Agreement — Conditions to Complete the Merger, page 87", "relevance_score": 5}, {"quote": "that (i) certain fundamental representations and warranties of QNB contained in the merger agreement must be true and correct in all material respects", "location": "qnbc-20260114.htm | The Merger Agreement — Conditions to Complete the Merger, page 87", "relevance_score": 5}, {"quote": "QNB must have performed in all material respects all obligations required to be performed by QNB under the merger agreement at or prior to the effective time", "location": "qnbc-20260114.htm | The Merger Agreement — Conditions to Complete the Merger, page 88", "relevance_score": 5}, {"quote": "Victory must have obtained the consent or approval of each person (other than governmental authorities) whose consent or approval is required in connection with the transactions contemplated by the merger agreement under any loan or credit agreement, note, mortgage, indenture, lease, license or other agreement or instrument in connection with the transactions contemplated by the merger agreement", "location": "qnbc-20260114.htm | The Merger Agreement — Conditions to Complete the Merger, page 88", "relevance_score": 5}, {"quote": "QNB must have received a written opinion from its counsel (or, if its counsel is unwilling or unable to issue the opinion, a written opinion of Victory’s counsel) dated as of the effective date of the merger, to the effect that, on the basis of facts, representations and assumptions set forth or referred to in the written opinion, the merger will qualify as a “reorganization” within the meaning of Section 368(a) of the Internal Revenue Code of 1986, as amended; and
•
the holders of no more than 10.0% of the issued and outstanding shares of Victory common stock shall have properly exercised dissenters’ rights of appraisal.", "location": "qnbc-20260114.htm | The Merger Agreement — Conditions to Complete the Merger, page 88", "relevance_score": 5}], "event_status": [{"quote": "On September 23, 2025, QNB Corp., or “QNB,” and The Victory Bancorp, Inc., or “Victory,” entered into an Agreement and Plan of Merger, which we refer to as the merger agreement, pursuant to which Victory will merge with and into QNB, with QNB surviving the merger, which we refer to as the merger.", "location": "qnbc-20260114.htm | Joint Proxy Statement/Prospectus, page i", "relevance_score": 5}, {"quote": "QNB and Victory currently anticipate completing the merger and filing the statement of merger with the Pennsylvania Department of State Bureau of Corporations and Charitable Organizations in the first quarter of 2026.", "location": "qnbc-20260114.htm | The Merger Agreement — Effective Time, page 84", "relevance_score": 5}], "security_description": [{"quote": "each share of Victory common stock issued and outstanding immediately prior to the effective time of the merger will be converted into the right to receive 0.5500 shares (the “exchange ratio”) of QNB common stock", "location": "qnbc-20260114.htm | Merger Consideration, page 12", "relevance_score": 5}, {"quote": "The Victory Bancorp, Inc. is a bank holding company headquartered in Limerick Township, Pennsylvania, and the parent company of The Victory Bank, a Pennsylvania state chartered bank that offers a full range of banking services from four offices across Montgomery and Berks Counties, Pennsylvania.", "location": "qnbc-20260114.htm | Summary — Information about Victory, page 11", "relevance_score": 5}], "effective_date": [{"quote": "QNB and Victory currently anticipate completing the merger and filing the statement of merger with the Pennsylvania Department of State Bureau of Corporations and Charitable Organizations in the first quarter of 2026.", "location": "qnbc-20260114.htm | The Merger Agreement — Effective Time, page 84", "relevance_score": 5}, {"quote": "The merger will become effective at the time at the later of the filing of the statement of merger with the Pennsylvania Department of State Bureau of Corporations and Charitable Organizations or such later date and time as set forth in such statement of merger (the “effective time”).", "location": "qnbc-20260114.htm | The Merger Agreement — Effective Time, page 84", "relevance_score": 5}], "available_options": [{"quote": "Under the terms of the merger agreement, holders of shares of Victory common stock (other than treasury shares and dissenters’ shares) will receive 0.5500 shares of QNB common stock for each share of Victory common stock they hold immediately prior to the effective time.", "location": "qnbc-20260114.htm | The Merger Agreement — Merger Consideration, page 84", "relevance_score": 5}], "default_option": [{"quote": "Under the terms of the merger agreement, holders of shares of Victory common stock (other than treasury shares and dissenters’ shares) will receive 0.5500 shares of QNB common stock for each share of Victory common stock they hold immediately prior to the effective time.", "location": "qnbc-20260114.htm | The Merger Agreement — Merger Consideration, page 84", "relevance_score": 5}], "election_deadline": []}
